import{G as e,W as t,n,rt as r}from"./chunks/framework.CHX_0itn.js";var i=JSON.parse(`{"title":"MAC 检测机制与原理","description":"","frontmatter":{"title":"MAC 检测机制与原理"},"headers":[],"relativePath":"traditional/MAC.md","filePath":"traditional/MAC.md"}`),a={name:`traditional/MAC.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="🪧-mac-检测原理" tabindex="-1">🪧 MAC 检测原理 <a class="header-anchor" href="#🪧-mac-检测原理" aria-label="Permalink to “🪧 MAC 检测原理”">​</a></h1><p>在校园网多设备检测的各种技术手段中，<strong>MAC 检测</strong>是二层接入场景中最直接的手段，常与 TTL、DHCP 指纹、流量特征等配合使用。</p><h2 id="❓-什么是-mac" tabindex="-1">❓ 什么是 MAC <a class="header-anchor" href="#❓-什么是-mac" aria-label="Permalink to “❓ 什么是 MAC”">​</a></h2><p>MAC（Media Access Control Address）是数据链路层地址，用于同一局域网内以太网帧的寻址。一个 MAC 地址长度为 <strong>48 位（6 字节）</strong>，通常写成 12 位十六进制数，例如 <code>00:1A:2B:3C:4D:5E</code>。</p><h3 id="mac-地址结构" tabindex="-1">MAC 地址结构 <a class="header-anchor" href="#mac-地址结构" aria-label="Permalink to “MAC 地址结构”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">部分</th><th style="text-align:left;">长度</th><th style="text-align:left;">含义</th></tr></thead><tbody><tr><td style="text-align:left;">OUI</td><td style="text-align:left;">前 3 字节</td><td style="text-align:left;">组织唯一标识符，可查询厂商</td></tr><tr><td style="text-align:left;">NIC Specific</td><td style="text-align:left;">后 3 字节</td><td style="text-align:left;">厂商分配给网卡的编号</td></tr><tr><td style="text-align:left;">I/G 位</td><td style="text-align:left;">第 1 字节 bit0</td><td style="text-align:left;">0 单播，1 组播</td></tr><tr><td style="text-align:left;">U/L 位</td><td style="text-align:left;">第 1 字节 bit1</td><td style="text-align:left;">0 全局管理，1 本地管理</td></tr></tbody></table><h3 id="📒-常见厂商-oui-前缀址类型" tabindex="-1">📒 常见厂商 OUI 前缀址类型 <a class="header-anchor" href="#📒-常见厂商-oui-前缀址类型" aria-label="Permalink to “📒 常见厂商 OUI 前缀址类型”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">厂商</th><th style="text-align:left;">常见 OUI 前缀</th><th style="text-align:left;">典型设备</th></tr></thead><tbody><tr><td style="text-align:left;">Apple</td><td style="text-align:left;"><code>3C:22:FB</code>、<code>A4:83:E7</code>、<code>F0:18:98</code></td><td style="text-align:left;">iPhone、iPad、Mac</td></tr><tr><td style="text-align:left;">Samsung</td><td style="text-align:left;"><code>00:1A:8A</code>、<code>34:23:BA</code>、<code>5C:0A:5B</code></td><td style="text-align:left;">手机、平板</td></tr><tr><td style="text-align:left;">Huawei</td><td style="text-align:left;"><code>00:E0:FC</code>、<code>28:6E:D4</code>、<code>48:DB:50</code></td><td style="text-align:left;">手机、路由器</td></tr><tr><td style="text-align:left;">Xiaomi</td><td style="text-align:left;"><code>00:9E:C8</code>、<code>28:6C:07</code>、<code>64:CC:2E</code></td><td style="text-align:left;">手机、IoT 设备</td></tr><tr><td style="text-align:left;">Intel</td><td style="text-align:left;"><code>00:1B:21</code>、<code>3C:97:0E</code>、<code>A4:5E:60</code></td><td style="text-align:left;">笔记本网卡</td></tr><tr><td style="text-align:left;">TP-Link</td><td style="text-align:left;"><code>00:1D:0F</code>、<code>14:CC:20</code>、<code>EC:08:6B</code></td><td style="text-align:left;">路由器</td></tr><tr><td style="text-align:left;">Realtek</td><td style="text-align:left;"><code>00:E0:4C</code>、<code>52:54:00</code></td><td style="text-align:left;">网卡</td></tr><tr><td style="text-align:left;">随机 MAC</td><td style="text-align:left;"><code>02:...</code>、<code>06:...</code>、<code>0A:...</code>、<code>0E:...</code></td><td style="text-align:left;">私有隐私随机 MAC</td></tr></tbody></table><h2 id="🔬-校园网检测-mac-的原理" tabindex="-1">🔬 校园网检测 MAC 的原理 <a class="header-anchor" href="#🔬-校园网检测-mac-的原理" aria-label="Permalink to “🔬 校园网检测 MAC 的原理”">​</a></h2><p>校园网认证网关或计费系统会在二层接入处记录源 MAC，检测服务商通常会维护一个 MAC 特征库，用于识别设备类型，这个特征库包含常见厂商的 OUI 前缀，单靠 MAC 检测很难发现多设备，需要结合 TTL、DHCP 指纹、User-Agent 等三层或应用层特征。</p><table tabindex="0"><thead><tr><th style="text-align:left;">其他手段判断的设备类型</th><th style="text-align:left;">抓取的 MAC 特征</th><th style="text-align:left;">校园网网关判定</th></tr></thead><tbody><tr><td style="text-align:left;">Windows 电脑</td><td style="text-align:left;">源 MAC = 电脑物理 MAC 或随机 MAC</td><td style="text-align:left;">唯一设备</td></tr><tr><td style="text-align:left;">Android 手机</td><td style="text-align:left;">源 MAC = 电脑物理 MAC</td><td style="text-align:left;">⚠️ <strong>封禁或增加封禁概率</strong></td></tr></tbody></table>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};